INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Getting Started$$, $$workspace-getting-started$$, 1);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-getting-started$$), $$workspace-getting-started-welcome$$, $$Welcome to your FVI Workspace$$, $$A Workspace is where you run reconciliations for one tenant and environment (Dev / Test / Prod). Use the **left rail** to navigate, the **Chrome / Canvas theme picker** to personalise, and **⌘K** to jump anywhere. The top-right shows your **profile menu** and **FVI - Copilot**.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-getting-started$$), $$workspace-getting-started-scopes$$, $$Understanding Workspace, Tenant, and Platform scopes$$, $$FVI has three scopes:
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-getting-started$$), $$workspace-getting-started-left-rail$$, $$Navigating the Workspace left rail$$, $$The left rail is grouped into **Workspace**, **Data ingestion**, **Reconcile**, **Insights**, **Governance**, and **Support**. Clicking an item updates the `?page=` URL so views are bookmarkable and shareable.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-getting-started$$), $$workspace-getting-started-envs$$, $$Switching environments (Dev / Test / Prod)$$, $$Use the environment chip at the top of the workspace. Definitions are promoted across environments via **Governance → Promotion** with 4-eyes approval.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-getting-started$$), $$workspace-getting-started-cmdk$$, $$Using ⌘K Command Palette$$, $$Press ⌘K (Ctrl+K on Windows) to open the global command palette. Search any page, recon definition, break, or KB article and jump in one keystroke.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-getting-started$$), $$workspace-getting-started-idle$$, $$Idle session and auto-logout$$, $$After 30 minutes of inactivity you receive a 1-minute warning before automatic sign-out. Move the mouse or press any key to extend the session.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Dashboard$$, $$workspace-dashboard$$, 2);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-dashboard$$), $$ws-dash-overview$$, $$Dashboard overview$$, $$The Dashboard surfaces match-rate trends, break severity, ageing, MTTR, top exception causes, and SLA health for the active environment. KPI tiles drill into the underlying break list.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-dashboard$$), $$ws-dash-match-rate$$, $$Reading the match-rate trend$$, $$The trend card shows matched vs unmatched volume over the selected time window. Hover any point for run-by-run breakdown.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-dashboard$$), $$ws-dash-severity$$, $$Severity and ageing tiles$$, $$Severity colours follow Critical → High → Medium → Low. Ageing buckets are 0–1d, 1–3d, 3–7d, 7d+. Click any segment to filter the **Break manager**.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-dashboard$$), $$ws-dash-range$$, $$Time range and comparison$$, $$Switch the range selector (Today / 7d / 30d / Custom) and toggle 'Compare to previous period' to see deltas.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Overview$$, $$workspace-overview$$, 3);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-overview$$), $$ws-overview-page$$, $$Workspace Overview page$$, $$The Overview page lists every active reconciliation in this workspace with last-run status, owner, schedule, and break count — a single operational view of the day's workload.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Ingestion Hub$$, $$workspace-ingestion-hub$$, 4);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-ingestion-hub$$), $$ws-ingest-what$$, $$Ingestion Hub: what it does$$, $$The Ingestion Hub is the single entry point for getting data into FVI. It groups **File uploads**, **Connections**, **File watchers**, **Data Prep**, **AIDP**, and **Reference data**.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-ingestion-hub$$), $$ws-ingest-choose$$, $$Choosing the right ingestion path$$, $$Use **File uploads** for one-off CSV/XLSX, **Connections** for SFTP/S3/Snowflake/BigQuery/Azure/DB/API, **File watchers** for automated pickup, **AIDP** for PDFs, and **Data Prep** to shape any of the above before recon.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · File uploads$$, $$workspace-file-uploads$$, 5);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-file-uploads$$), $$ws-up-csv$$, $$Uploading a CSV or XLSX file$$, $$Open **Data ingestion → File uploads**, drag the file in, choose delimiter and header row, and FVI auto-profiles columns. Files are encrypted at rest in your tenant bucket.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-file-uploads$$), $$ws-up-formats$$, $$Supported file formats and limits$$, $$CSV, TSV, XLSX, XLS, JSON, Parquet. Default per-file cap is 200 MB; contact your tenant admin to raise it.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-file-uploads$$), $$ws-up-versions$$, $$Re-uploading and version handling$$, $$Re-uploading the same logical file creates a new version. Reconciliations can be pinned to 'latest' or to a specific version.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Connections$$, $$workspace-connections$$, 6);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-connections$$), $$ws-conn-overview$$, $$Connections overview$$, $$Connections are reusable, scheduled pipes from external systems. We support SFTP, S3, Azure Blob, GCS, Snowflake, BigQuery, Postgres/MySQL/SQL Server, REST API, Kafka, and Webhooks.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-connections$$), $$ws-conn-sftp$$, $$Creating an SFTP connection$$, $$Provide host, port, username, key/password, and the source path/pattern. Use **Test connection** before saving. Credentials are stored encrypted with the platform data encryption key.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-connections$$), $$ws-conn-objstore$$, $$Creating an S3 / Azure Blob / GCS connection$$, $$Supply bucket/container, region, prefix, and IAM credentials or SAS token. Optional KMS key id for BYOK environments.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-connections$$), $$ws-conn-db$$, $$Creating a Snowflake / BigQuery / Postgres connection$$, $$Choose database engine, host, warehouse/dataset, user, password (or service-account JSON), and SQL statement or table name.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-connections$$), $$ws-conn-api$$, $$Creating a REST API connection$$, $$Define base URL, auth header, pagination strategy (page / cursor / link-header), and JSON path to records.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-connections$$), $$ws-conn-sched$$, $$Scheduling a connection pull$$, $$Each connection has its own cron — 5 min minimum interval. Failures retry with exponential backoff and surface in **Run history**.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · File watchers$$, $$workspace-file-watchers$$, 7);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-file-watchers$$), $$ws-watch-what$$, $$File watchers explained$$, $$A watcher monitors a connection path/prefix and triggers downstream pipelines (Data Prep → Recon) whenever a matching file lands.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-file-watchers$$), $$ws-watch-patterns$$, $$Watcher patterns and naming rules$$, $$Use glob patterns (`*.csv`, `nostro_*_2026*.xlsx`). Watchers respect file-stable wait time to avoid picking up partial uploads.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Data Prep$$, $$workspace-data-prep$$, 8);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-data-prep$$), $$ws-prep-pipelines$$, $$Data Prep pipelines$$, $$A Data Prep pipeline is a chain of transforms applied to a source before reconciliation. Pipelines are versioned and have unique IDs (`DP-YYYYMMDD-xxxxxxxx`).$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-data-prep$$), $$ws-prep-catalog$$, $$Transform catalog (42 transforms)$$, $$Includes trim, cast, split, concat, regex extract, lookup, dedupe, pivot, unpivot, filter, fill nulls, currency normalise, date parse, FX convert, derive, mask PII, hash, validate against schema, and more.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-data-prep$$), $$ws-prep-dq$$, $$Data quality rules$$, $$Attach DQ rules (not-null, unique, regex, range, referential) to any column. Failing rows can be quarantined or block the run.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-data-prep$$), $$ws-prep-history$$, $$Pipeline run history (90-day configurable)$$, $$Every run is logged with row counts, rejects, duration, and lineage to the producing connection.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · AIDP$$, $$workspace-aidp$$, 9);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-aidp$$), $$ws-aidp-what$$, $$AIDP: Adaptive Intelligent Document Processing$$, $$AIDP extracts structured tables from PDFs (custody statements, trade confirms, broker reports). It learns from corrections per template.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-aidp$$), $$ws-aidp-train$$, $$Training an AIDP template$$, $$Upload a sample PDF, draw column regions or accept AI-detected ones, label fields, then publish the template. Subsequent PDFs of that layout are extracted automatically.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Reference data$$, $$workspace-reference-data$$, 10);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-reference-data$$), $$ws-ref-sets$$, $$Reference data sets$$, $$Maintain currency tables, holiday calendars, counterparty mappings, security master, and account hierarchies. Reference sets are versioned and joinable inside Data Prep.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Rekon Studio$$, $$workspace-rekon-studio$$, 11);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-what$$, $$What is Rekon Studio$$, $$Rekon Studio is the wizard for designing reconciliations. It supports **One-sided**, **Two-sided**, and **Three-sided** modes with 20+ deterministic matching rules plus probabilistic and ML-confidence matching.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-modes$$, $$One-sided, two-sided, three-sided modes$$, $$**One-sided** validates a single source against rules. **Two-sided** matches A ↔ B (the classic case). **Three-sided** matches A ↔ B ↔ C (e.g. trade ↔ confirm ↔ settlement).$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-wizard$$, $$Wizard walkthrough$$, $$Steps: 1) Name & scope, 2) Sources (File / Paste / API / DB / PDF / Refined dataset), 3) Mapping, 4) Matching rules, 5) Tolerances, 6) Exception routing, 7) Review & save.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-connectors$$, $$Connector types in the wizard$$, $$File upload, Paste data, REST API, Database (Postgres/MySQL/SQL Server), PDF via AIDP, Refined dataset (Data Prep output), Existing source.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-automap$$, $$Auto-detect column mapping$$, $$FVI proposes mappings using header similarity, sample-value type inference, and an LLM second-opinion. Accept, override, or describe in plain English.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-nl$$, $$Describe-in-English mapping$$, $$Type 'map TradeID to TxnRef and convert amount from cents to dollars' — FVI generates the mapping and a Data Prep transform if needed.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-preview$$, $$Mapping preview panel$$, $$Shows a live 50-row sample of the joined, normalised data with rule hit/miss indicators before you save.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-rules$$, $$Matching rule library$$, $$1:1 exact, 1:1 tolerance, 1:many, many:1, many:many, fuzzy string, soundex, date-window, amount + currency, composite key, conditional rule set, FX-aware, hash-bucketed, and ML-confidence.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-tol$$, $$Tolerances and rounding$$, $$Per-rule absolute, percentage, and bps tolerances; currency-aware rounding; FX rate source and date selector.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-save$$, $$Saving and versioning a definition$$, $$Saving creates an immutable version. Diff and rollback are available from **Version history**. Promotion across Dev/Test/Prod requires 4-eyes approval.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-clone$$, $$Cloning a reconciliation$$, $$Use **Clone** to start from an existing definition. Cloned defs are draft until reviewed and promoted.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-studio$$), $$ws-rk-edit$$, $$Editing or deleting a definition safely$$, $$Edits create a new draft version; the running version is unaffected. Delete is soft — definition is archived and runs are retained per tenant retention policy.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Rekon Orchestrator$$, $$workspace-rekon-orchestrator$$, 12);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-orchestrator$$), $$ws-orch-overview$$, $$Rekon Orchestrator overview$$, $$The Orchestrator schedules and chains reconciliations. Cron, event-driven (watcher), or manual triggers. Dependencies between recons are honoured.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-orchestrator$$), $$ws-orch-create$$, $$Creating a schedule$$, $$Pick cron expression or visual builder, set timezone, max concurrency, and SLA. Failures fan out to the Channels you've configured.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-rekon-orchestrator$$), $$ws-orch-pause$$, $$Pausing, resuming, back-filling$$, $$Pause a schedule without losing definition. Back-fill replays a date range against the current definition for audit / re-grading.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Run history$$, $$workspace-run-history$$, 13);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-run-history$$), $$ws-runs-read$$, $$Reading the Run history$$, $$Each row shows run UID (`R-YYYYMMDD-xxxxxxxx`), trigger, duration, matched / unmatched counts, exceptions raised, and status.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-run-history$$), $$ws-runs-rerun$$, $$Re-running and reprocessing$$, $$Re-run uses the same inputs against the current definition version. Reprocessing re-pulls source data first.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-run-history$$), $$ws-runs-retention$$, $$Run retention$$, $$Defaults to 90 days, configurable per tenant. Older runs are purged nightly by the platform purge job.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Template gallery$$, $$workspace-template-gallery$$, 14);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-template-gallery$$), $$ws-tpl-gallery$$, $$Template gallery$$, $$Pre-built reconciliation templates: Cash & Bank Nostro, Securities & Trades, Intercompany / GL, Custody, Collateral / CSA, NAV, and regulatory packs (EMIR, DORA, MiFID II, T+1).$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-template-gallery$$), $$ws-tpl-use$$, $$Using a template$$, $$Click any template to spawn a new Rekon Studio draft pre-filled with sources, mappings, and rules. Adjust to your accounts and save.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Collateral / CSA$$, $$workspace-collateral-csa$$, 15);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-collateral-csa$$), $$ws-csa-recon$$, $$Collateral / CSA reconciliation$$, $$Reconciles collateral movements against ISDA CSA agreements — eligible collateral, haircuts, thresholds, MTA, IA vs VM, and dispute markers.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Exceptions$$, $$workspace-exceptions$$, 16);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-exceptions$$), $$ws-exc-list$$, $$Exceptions list$$, $$Every unmatched record or rule failure becomes an exception. Filter by severity, age, owner, rule, and source.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-exceptions$$), $$ws-exc-bulk$$, $$Bulk actions on exceptions$$, $$Assign, comment, tag, close, escalate, or export selected exceptions in bulk. Bulk close requires a reason code.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-exceptions$$), $$ws-exc-export$$, $$Exporting exceptions$$, $$Export CSV / JSON / XLSX with a digitally signed manifest for audit chain-of-custody.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Break manager$$, $$workspace-break-manager$$, 17);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-break-manager$$), $$ws-bm-overview$$, $$Break manager overview$$, $$Kanban-style triage board with columns for New, Investigating, Pending counterparty, Resolved, Cancelled. Drag cards between lanes.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-break-manager$$), $$ws-bm-inspector$$, $$Break inspector (side-by-side)$$, $$Opens A vs B (or A/B/C) records side-by-side with diff highlighting on every field. Linked notes, attachments, and audit trail in the right panel.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-break-manager$$), $$ws-bm-lifecycle$$, $$Lifecycle states and MTTR$$, $$Each transition is timestamped; MTTR and SLA timers track against the **SLA** policy your tenant admin configured.$$, 'published');
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-break-manager$$), $$ws-bm-notes$$, $$Notes, mentions, attachments$$, $$Add markdown notes, mention teammates (they receive Channel notification), and attach evidence files.$$, 'published');
INSERT INTO kb_categories(scope, tenant_id, name, slug, position) VALUES ('platform', NULL, $$Workspace · Proposed matches$$, $$workspace-proposed-matches$$, 18);
INSERT INTO kb_articles(scope, tenant_id, category_id, slug, title, body_md, status) VALUES ('platform', NULL, (SELECT id FROM kb_categories WHERE scope='platform' AND tenant_id IS NULL AND slug=$$workspace-proposed-matches$$), $$ws-prop-what$$, $$Proposed matches$$, $$The AI agent and probabilistic engine surface high-confidence candidate matches that didn't meet deterministic thresholds. Each has a confidence score and explanation.$$, 'published');
